from __future__ import annotations

def build_entry_blocker_surface(entry_info: facade.Mapping[str, facade.Any] | None, *, final_decision: facade.Any, no_trade_surface: facade.Mapping[str, facade.Any] | None=None, entry_blockers: facade.Sequence[facade.Any] | None=None, buy_blocked_open_position: bool=False, buy_blocked_closeout_window: bool=False, buy_blocked_post_exit_cooldown: bool=False, post_exit_cooldown_remaining_sec: facade.Any=None, open_position_count: facade.Any=None, minutes_to_close: facade.Any=None, eod_flat_cutoff_min: facade.Any=None, facade: facade.Any) -> facade.Dict[str, facade.Any]:
    row = dict(entry_info or {}) if isinstance(entry_info, facade.Mapping) else {}
    no_trade = dict(no_trade_surface or {}) if isinstance(no_trade_surface, facade.Mapping) else {}
    metrics = dict(row.get('metrics') or {}) if isinstance(row.get('metrics'), facade.Mapping) else {}
