    primary_blockers = facade._dedupe_non_empty([dominant_blocker, no_trade_code] + list(no_trade.get('required_checks_failed') or []) + list(no_trade.get('preferred_checks_failed') or []) + list(no_trade.get('relaxable_checks_failed') or []), limit=8)
    raw_entry_blockers = facade._dedupe_non_empty(list(entry_blockers or []), limit=8)
    if not primary_blockers:
        primary_blockers = list(raw_entry_blockers)
    elif len(primary_blockers) < 2 and raw_entry_blockers:
        primary_blockers = facade._dedupe_non_empty(list(primary_blockers) + list(raw_entry_blockers), limit=8)
    volume_ok = facade._resolve_check_state(name='volume_ok', metrics=metrics, passed_checks=passed_checks, failed_checks=failed_checks, check_status=check_status)
    rebound_ok = facade._resolve_check_state(name='rebound_ok', metrics=metrics, passed_checks=passed_checks, failed_checks=failed_checks, check_status=check_status)
