    confidence_score = facade._to_float(metrics.get('confidence_score', condition_scores.get('confidence_score')))
    confidence_threshold = facade._to_float(metrics.get('confidence_threshold', condition_scores.get('confidence_threshold')))
    confidence_gap = max(0.0, confidence_threshold - confidence_score) if confidence_threshold > 0.0 else 0.0
    confidence_near_miss = bool(final_outcome not in {'BUY', 'SELL'} and confidence_threshold > 0.0 and (0.0 < confidence_gap <= 0.005))
    cooldown_remaining = facade._to_int(post_exit_cooldown_remaining_sec)
    volume_missing = no_trade_code == 'volume_confirmation_missing' or dominant_blocker == 'volume_confirmation_missing'
    pullback_not_mature = no_trade_code == 'pullback_not_mature' or dominant_blocker == 'pullback_not_mature'
    reclaim_blocked = no_trade_code == 'below_vwap_reclaim_not_ready' or dominant_blocker == 'below_vwap_reclaim_not_ready'
    reclaim_gate_ok = facade._resolve_check_state(name='reclaim_gate_ok', metrics=metrics, passed_checks=passed_checks, failed_checks=failed_checks, check_status=check_status)
    vwap_hold_ok = facade._resolve_check_state(name='vwap_hold_ok', metrics=metrics, passed_checks=passed_checks, failed_checks=failed_checks, check_status=check_status)
    vwap_reclaim_ok = facade._resolve_check_state(name='vwap_reclaim_ok', metrics=metrics, passed_checks=passed_checks, failed_checks=failed_checks, check_status=check_status)
    reclaim_readiness_tuned = bool(policy_gating.get('reclaim_readiness_tuned'))
    reclaim_distance_to_ready = metrics.get('reclaim_distance_to_ready', row.get('reclaim_distance_to_ready'))
    reclaim_evidence_explanation = facade._reclaim_evidence_explanation(reclaim_blocked=reclaim_blocked, reclaim_gate_ok=reclaim_gate_ok, vwap_hold_ok=vwap_hold_ok, vwap_reclaim_ok=vwap_reclaim_ok, reclaim_distance_to_ready=reclaim_distance_to_ready, reclaim_readiness_tuned=reclaim_readiness_tuned)
    return {'schema_version': 'entry_blocker_surface.v1', 'final_decision': final_outcome, 'no_trade_code': no_trade_code, 'dominant_blocker': dominant_blocker, 'primary_blockers': primary_blockers, 'raw_entry_blockers': raw_entry_blockers, 'entry_style': str(policy_interpretation.get('entry_style') or '').strip(), 'confidence_score': metrics.get('confidence_score', condition_scores.get('confidence_score')), 'confidence_threshold': metrics.get('confidence_threshold', condition_scores.get('confidence_threshold')), 'confidence_gap': round(confidence_gap, 4) if confidence_threshold > 0.0 else None, 'confidence_near_miss': confidence_near_miss, 'entry_probe_candidate': bool(confidence_near_miss and bool(no_trade.get('near_ready_flag'))), 'entry_quality_score': metrics.get('entry_quality_score', condition_scores.get('entry_quality_score')), 'entry_quality_tier': metrics.get('entry_quality_tier', condition_scores.get('entry_quality_tier')), 'entry_quality_path': metrics.get('entry_quality_path', condition_scores.get('entry_quality_path')), 'entry_quality_observability_only': bool(metrics.get('entry_quality_observability_only', condition_scores.get('entry_quality_observability_only'))), 'rebound_ok': rebound_ok, 'rebound_progress': metrics.get('rebound_progress'), 'pullback_ok': pullback_ok, 'pullback_mature': metrics.get('pullback_mature'), 'pullback_not_too_deep': metrics.get('pullback_not_too_deep'), 'pullback_not_mature': bool(pullback_not_mature), 'pullback_depth_pct': metrics.get('pullback_depth_pct', metrics.get('pullback_pct')), 'volume_ok': volume_ok, 'volume_ratio': metrics.get('volume_ratio'), 'volume_confirmation_missing': bool(volume_missing), 'previous_close': metrics.get('previous_close'), 'session_open': metrics.get('session_open'), 'open_gap_pct': metrics.get('open_gap_pct'), 'prev_close_distance_pct': metrics.get('prev_close_distance_pct'), 'minutes_since_session_open': metrics.get('minutes_since_session_open'), 'opening_gap_chase_observed': bool(metrics.get('opening_gap_chase_observed')), 'opening_gap_context_observation_only': bool(metrics.get('opening_gap_context_observation_only')), 'structure_hh_hl': structure_state, 'breakout_ok': facade._resolve_check_state(name='breakout_ok', metrics=metrics, passed_checks=passed_checks, failed_checks=failed_checks, check_status=check_status), 'below_vwap_reclaim_not_ready': bool(reclaim_blocked), 'reclaim_gate_ok': reclaim_gate_ok, 'vwap_hold_ok': vwap_hold_ok, 'vwap_reclaim_ok': vwap_reclaim_ok, 'reclaim_distance_to_ready': reclaim_distance_to_ready, 'reclaim_readiness_tuned': reclaim_readiness_tuned, 'reclaim_tuning_version': str(policy_gating.get('reclaim_tuning_version') or ''), 'reclaim_tuning_scope': str(policy_gating.get('reclaim_tuning_scope') or ''), 'reclaim_tuning_band_used': str(policy_gating.get('reclaim_tuning_band_used') or ''), 'reclaim_near_ready_distance_min': policy_gating.get('reclaim_near_ready_distance_min'), 'entry_tuning_flags': facade._dedupe_non_empty(list(policy_gating.get('entry_tuning_flags') or []), limit=6), 'reclaim_evidence_explanation': reclaim_evidence_explanation, 'open_position_blocked': bool(buy_blocked_open_position), 'closeout_window_blocked': bool(buy_blocked_closeout_window), 'cooldown_blocked': bool(buy_blocked_post_exit_cooldown), 'post_exit_cooldown_remaining_sec': cooldown_remaining, 'open_position_count': facade._to_int(open_position_count), 'minutes_to_close': minutes_to_close, 'eod_flat_cutoff_min': eod_flat_cutoff_min, 'entry_reason': str(row.get('reason') or '').strip(), 'primary_failure_axis': str(row.get('primary_failure_axis') or '').strip(), 'transition_readiness_score': metrics.get('transition_readiness_score')}
